import {createCardPrices} from './card-prices.mjs';
import {createSkinInspector} from './skin-inspector.mjs';
import {createMarketPrices} from './market-prices.mjs';
import {filterCatalog,rarityNames,wearNames} from './catalog-data.mjs';
const el=(tag,className,text)=>{const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node};
const picture=(src,alt)=>{const img=el('img');img.alt=alt;img.loading='lazy';img.decoding='async';img.src=src;img.onerror=()=>{img.onerror=null;img.src='assets/image-unavailable.svg'};return img};
export function createExplorer(root,{onEquip}){
 const $=s=>root.querySelector(s),dialog=document.querySelector('#catalogDialog');const inspector=createSkinInspector(dialog),prices=createMarketPrices(dialog),cardPrices=createCardPrices(root);let context,activeWeapon='AWP',activeCategory='',limit=36,matches=[],chosen=null;
 const filters=()=>({weapon:activeWeapon,category:activeCategory,query:$('#search').value,rarities:[...root.querySelectorAll('[name=rarity]:checked')].map(n=>n.value),wear:$('#catalogWear').value,variant:$('#catalogVariant').value,min:Number($('#floatMin').value||0),max:$('#floatMax').value||'1',sort:$('#catalogSort').value});
 function choose(weapon,category=''){activeWeapon=weapon;activeCategory=category;$('#search').value='';root.querySelectorAll('details').forEach(d=>d.open=false);limit=36;render()}
 function navigation(){
  const nav=$('#catalogCategories');nav.replaceChildren();const all=el('button','catalog-all','⌕  Todas las skins');all.onclick=()=>choose('');nav.append(all);
  for(const name of ['Cuchillos','Guantes','Pistolas','Rifles','Subfusiles','Pesadas','Equipo']){
   const group=el('details','catalog-category'),summary=el('summary','',name+' ⌄'),menu=el('div','catalog-dropdown'),allGroup=el('button','','Ver '+name.toLowerCase()+' →');allGroup.onclick=()=>choose('',name);menu.append(allGroup);
   for(const model of context.models.filter(m=>m.category===name)){const b=el('button');b.append(picture(context.items.find(s=>s.weapon===model.name&&s.vanilla)?.image||context.items.find(s=>s.weapon===model.name)?.image,''),el('span','',model.name));b.onclick=()=>choose(model.name);menu.append(b)}
   group.append(summary,menu);group.addEventListener('toggle',()=>{if(group.open)for(const other of nav.querySelectorAll('details'))if(other!==group)other.open=false});nav.append(group);
  }
 }
 function rarityFilters(){const area=$('#catalogRarities'),selected=new Set([...area.querySelectorAll(':checked')].map(x=>x.value));area.replaceChildren();
  for(const [name,label]of Object.entries(rarityNames)){const item=context.items.find(s=>context.details[s.id]?.rarity===name&&!s.vanilla);if(!item)continue;const row=el('label','catalog-check'),input=el('input');input.type='checkbox';input.name='rarity';input.value=name;input.checked=selected.has(name);input.onchange=refresh;const dot=el('span','rarity-dot');dot.style.background=item.color;row.append(input,dot,document.createTextNode(label));area.append(row)}
 }
 function refresh(){limit=36;render()}
 function render(){if(!context)return;const {items,models,details}=context,f=filters();matches=filterCatalog(items,models,details,f);
  const title=activeWeapon||activeCategory||($('#search').value?'Resultados de búsqueda':'Todas las skins');$('#catalogTitle').textContent=title;$('#catalogBreadcrumb').textContent='Catálogo / '+title;$('#catalogCount').textContent=matches.length.toLocaleString('es');$('#catalogResults').textContent=matches.length+' acabados'+(activeWeapon?' de '+activeWeapon:'');
  $('#catalogScope').textContent=activeWeapon?'EXPLORAR '+activeWeapon.toUpperCase():'TU PRÓXIMA COMBINACIÓN';$('#catalogCollectionCount').textContent=new Set(matches.flatMap(s=>(details[s.id]?.collections||[]).map(c=>c.name))).size;$('#catalogModelCount').textContent=new Set(matches.map(s=>s.weapon)).size;
  const hero=items.find(s=>s.weapon===activeWeapon&&s.vanilla)||matches[0];$('#catalogHeroImg').src=hero?.image||'assets/image-unavailable.svg';$('#catalogHeroImg').alt=activeWeapon||'Selección de skins';$('#catalogHeroName').textContent=title;$('#catalogHeroDescription').textContent=activeWeapon?'Todos sus acabados, colecciones y rangos de desgaste. Encuentra tu próxima skin y guárdala en tu equipamiento.':'Explora armas, cuchillos y guantes. Filtra por rareza, colección, desgaste o acabado.';
  $('#catalogFilterError').textContent=Number(f.min)>Number(f.max)?'El float mínimo debe ser menor que el máximo.':'';
  const selectedCategory=activeCategory||models.find(m=>m.name===activeWeapon)?.category;root.querySelectorAll('.catalog-category').forEach(g=>g.classList.toggle('is-current',!!selectedCategory&&g.querySelector('summary').textContent===selectedCategory+' ⌄'));
  const grid=$('#skins');grid.replaceChildren(...matches.slice(0,limit).map(card));if(!matches.length){const empty=el('div','catalog-empty');empty.append(el('span','','⌕'),el('h3','','No encontramos esa combinación'),el('p','','Prueba otro nombre o restablece los filtros.'));grid.append(empty)}$('#catalogMore').hidden=matches.length<=limit;$('#catalogMore').textContent='Ver más acabados · '+Math.min(limit,matches.length)+' de '+matches.length;cardPrices.observe();
 }
 function floatBar(d){const wrap=el('div','catalog-float'),bar=el('div','float-track');for(let i=0;i<40;i++){const tick=el('span');tick.style.setProperty('--tick',i/39*100+'%');if(d.min!=null&&i/40>=d.min&&i/40<=d.max)tick.className='in-range';bar.append(tick)}wrap.append(bar,el('span','float-caption',d.min==null?'Sin desgaste':d.min.toFixed(2)+' — '+d.max.toFixed(2)));return wrap}
 function card(s){const d=context.details[s.id]||{},article=el('article','catalog-card');article.style.setProperty('--rarity',s.color);const button=el('button','catalog-card-open');button.setAttribute('aria-label','Ver '+s.weapon+' · '+s.name);
  const heading=el('div','catalog-card-heading'),tags=el('div','catalog-tags');tags.append(el('span','',s.weapon));if(d.stattrak)tags.append(el('span','variant-st','ST'));if(d.souvenir)tags.append(el('span','variant-sv','SV'));heading.append(tags,el('span','catalog-rarity',rarityNames[d.rarity]||d.rarity||'Acabado'));
  const collection=el('div','catalog-collection');if(d.collections?.[0])collection.append(picture(d.collections[0].image,''),el('span','',d.collections[0].name));else collection.append(el('span','','Sin colección asociada'));
  const media=el('div','catalog-card-media');media.append(picture(s.image,s.weapon+' · '+s.name));button.append(heading,el('h3','',s.name),collection,el('p','catalog-crates','◇  '+(d.crates?d.crates+' contenedores':'Sin contenedores')),media,floatBar(d));button.onclick=()=>openSkin(s);
  const foot=el('button','catalog-card-footer'),teams=context.models.find(m=>m.name===s.weapon).teams,current=teams.filter(t=>context.state[t]?.[s.weapon]?.current===s.id),desired=teams.filter(t=>context.state[t]?.[s.weapon]?.desired===s.id),label=current.length?'✓ Actual · '+current.join('/') :desired.length?'♡ En tu lista · '+desired.join('/'):'Ver acabado y precios';foot.append(el('span','',label),el('span','','↗'));foot.onclick=()=>openSkin(s);const market=el('div','card-market-prices'),f=filters();market.dataset.priceSkin=s.id;market.dataset.priceWear=f.wear||'';market.dataset.priceVariant=f.variant||'normal';market.append(el('small','card-price-condition','Consultando mercados · USD'));for(const provider of ['steam','csfloat']){const row=el('div','card-price-row'),value=el('strong','','…');value.dataset.priceProvider=provider;row.append(el('span','',provider==='steam'?'Steam':'CSFloat'),value);market.append(row)}article.append(button,market,foot);return article;
 }
 function openSkin(s){chosen=s;const d=context.details[s.id]||{};dialog.querySelector('#catalogDetailName').textContent=s.name;dialog.querySelector('#catalogDetailWeapon').textContent=s.weapon;dialog.querySelector('#catalogDetailImage').src=s.image;dialog.querySelector('#catalogDetailImage').alt=s.weapon+' · '+s.name;dialog.querySelector('#catalogDetailMeta').textContent=[rarityNames[d.rarity]||d.rarity,...(d.collections||[]).map(c=>c.name)].filter(Boolean).join(' · ');const teams=context.models.find(m=>m.name===s.weapon).teams,select=dialog.querySelector('#catalogEquipTeam');select.replaceChildren(...teams.map(t=>new Option(t==='CT'?'CT · Antiterroristas':'T · Terroristas',t)));select.value=teams.includes(context.team)?context.team:teams[0];dialog.querySelector('#catalogDetailFloat').replaceChildren(floatBar(d));dialog.showModal();inspector.open(s,context.viewers[s.id]);prices.open(s)}
 for(const button of dialog.querySelectorAll('[data-catalog-equip]'))button.onclick=()=>{if(chosen)onEquip(chosen,dialog.querySelector('#catalogEquipTeam').value,button.dataset.catalogEquip);dialog.close()};dialog.querySelector('#catalogDetailClose').onclick=()=>dialog.close();
 $('#catalogToggleFilters').onclick=()=>{const open=root.classList.toggle('filters-open');$('#catalogToggleFilters').setAttribute('aria-expanded',open);};
 $('#search').oninput=()=>{activeWeapon='';activeCategory='';refresh()};for(const id of ['catalogWear','catalogVariant','floatMin','floatMax','catalogSort'])$('#'+id).onchange=refresh;
 $('#catalogReset').onclick=()=>{root.querySelectorAll('[name=rarity]').forEach(n=>n.checked=false);$('#catalogWear').value='';$('#catalogVariant').value='';$('#floatMin').value='0';$('#floatMax').value='1';$('#search').value='';refresh()};$('#catalogMore').onclick=()=>{limit+=36;render()};
 document.addEventListener('click',e=>{if(!e.target.closest('.catalog-category'))root.querySelectorAll('details').forEach(d=>d.open=false)});root.addEventListener('keydown',e=>{if(e.key==='Escape')root.querySelectorAll('details').forEach(d=>d.open=false)});
 return{update(next){const first=!context;context=next;if(first){navigation();rarityFilters();$('#catalogWear').replaceChildren(new Option('Cualquier desgaste',''),...Object.entries(wearNames).map(([value,label])=>new Option(label,value)))}render()}};
}
